/* Small, dependency-free inference runtime for the FocusGuard answer model.
 * The matching weights and vocabulary are generated by train_guard.py.
 */
(function (root) {
  "use strict";

  const TOKEN_RE = /[\p{L}]+(?:['’][\p{L}]+)?|\p{N}+|[^\s]/gu;

  function sigmoid(x) {
    if (x >= 0) { const z = Math.exp(-x); return 1 / (1 + z); }
    const z = Math.exp(x); return z / (1 + z);
  }

  function tokenize(text) {
    return (String(text).toLowerCase().match(TOKEN_RE) || []);
  }

  async function load(baseUrl) {
    const base = baseUrl.endsWith("/") ? baseUrl : baseUrl + "/";
    const [metaResponse, vocabResponse, weightResponse] = await Promise.all([
      fetch(base + "meta.json"), fetch(base + "vocab.json"), fetch(base + "weights.bin")
    ]);
    if (!metaResponse.ok || !vocabResponse.ok || !weightResponse.ok) {
      throw new Error("model files are missing");
    }
    const [meta, vocab, bytes] = await Promise.all([
      metaResponse.json(), vocabResponse.json(), weightResponse.arrayBuffer()
    ]);
    const weights = new Float32Array(bytes);
    if (weights.length !== meta.weight_count || vocab.length !== meta.vocab_size) {
      throw new Error("model files do not match; retrain and copy all three files together");
    }

    const tensor = (name) => {
      const spec = meta.tensors[name];
      return weights.subarray(spec.offset, spec.offset + spec.size);
    };
    const wordToId = new Map(vocab.map((word, id) => [word, id]));
    const d = meta.d_model;
    const heads = meta.n_heads;
    const headDim = d / heads;
    const eps = meta.layer_norm_eps;

    function linear(x, weight, bias, outDim, inDim) {
      const y = new Float32Array(outDim);
      for (let o = 0; o < outDim; o++) {
        let sum = bias[o];
        const row = o * inDim;
        for (let i = 0; i < inDim; i++) sum += weight[row + i] * x[i];
        y[o] = sum;
      }
      return y;
    }

    function layerNorm(x, gamma, beta) {
      let mean = 0;
      for (let i = 0; i < d; i++) mean += x[i];
      mean /= d;
      let variance = 0;
      for (let i = 0; i < d; i++) { const z = x[i] - mean; variance += z * z; }
      variance /= d;
      const inv = 1 / Math.sqrt(variance + eps);
      const y = new Float32Array(d);
      for (let i = 0; i < d; i++) y[i] = (x[i] - mean) * inv * gamma[i] + beta[i];
      return y;
    }

    function gelu(x) {
      const c = 0.7978845608028654;
      return 0.5 * x * (1 + Math.tanh(c * (x + 0.044715 * x * x * x)));
    }

    function evaluate(text) {
      const tokens = tokenize(text).slice(0, meta.max_length - 1);
      const ids = [meta.cls_id, ...tokens.map((token) => wordToId.get(token) ?? meta.unk_id)];
      const length = ids.length;
      const x = Array.from({ length }, (_, pos) => {
        const id = ids[pos];
        const sentimentId = meta.sentiment_ids[id] || 0;
        const v = new Float32Array(d);
        const word = tensor("embedding");
        const sent = tensor("sentiment_embedding");
        const position = tensor("position_embedding");
        const po = pos * d;
        const wo = id * d;
        const so = sentimentId * d;
        for (let j = 0; j < d; j++) v[j] = word[wo + j] + sent[so + j] + position[po + j];
        return v;
      });

      // One pre-layer-normalized transformer encoder block.
      const normalized = x.map((v) => layerNorm(v, tensor("ln1_weight"), tensor("ln1_bias")));
      const q = normalized.map((v) => linear(v, tensor("q_weight"), tensor("q_bias"), d, d));
      const k = normalized.map((v) => linear(v, tensor("k_weight"), tensor("k_bias"), d, d));
      const value = normalized.map((v) => linear(v, tensor("v_weight"), tensor("v_bias"), d, d));
      for (let i = 0; i < length; i++) {
        const joined = new Float32Array(d);
        for (let h = 0; h < heads; h++) {
          const start = h * headDim;
          const scores = new Float32Array(length);
          let max = -Infinity;
          for (let j = 0; j < length; j++) {
            let dot = 0;
            for (let z = 0; z < headDim; z++) dot += q[i][start + z] * k[j][start + z];
            scores[j] = dot / Math.sqrt(headDim);
            if (scores[j] > max) max = scores[j];
          }
          let total = 0;
          for (let j = 0; j < length; j++) { scores[j] = Math.exp(scores[j] - max); total += scores[j]; }
          for (let z = 0; z < headDim; z++) {
            let sum = 0;
            for (let j = 0; j < length; j++) sum += (scores[j] / total) * value[j][start + z];
            joined[start + z] = sum;
          }
        }
        const projected = linear(joined, tensor("o_weight"), tensor("o_bias"), d, d);
        for (let j = 0; j < d; j++) x[i][j] += projected[j];
      }

      const hidden = meta.d_ff;
      for (let i = 0; i < length; i++) {
        const n = layerNorm(x[i], tensor("ln2_weight"), tensor("ln2_bias"));
        const f = linear(n, tensor("ff1_weight"), tensor("ff1_bias"), hidden, d);
        for (let j = 0; j < hidden; j++) f[j] = gelu(f[j]);
        const y = linear(f, tensor("ff2_weight"), tensor("ff2_bias"), d, hidden);
        for (let j = 0; j < d; j++) x[i][j] += y[j];
      }

      const logit = linear(x[0], tensor("head_weight"), tensor("head_bias"), 1, d)[0];
      let polarity = 0;
      for (const id of ids.slice(1)) polarity += meta.sentiment_scores[id] || 0;
      if (ids.length > 1) polarity /= ids.length - 1;
      return { pReal: sigmoid(logit), polarity };
    }

    return { evaluate, threshold: meta.threshold, meta };
  }

  root.FocusGuardModel = { load, tokenize };
})(globalThis);
